import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B);
"""

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>
#include <algorithm>

#include <cute/tensor.hpp>

using namespace cute;

// Split-K tiled GEMM: C(M,N) += A(M,K) * B(K,N)
// A is (M,K) row-major, B is (K,N) row-major, C is (M,N) row-major.
// Multi-stage cp.async software pipeline over the huge K reduction: while
// the CTA computes on one shared-memory stage, subsequent K-tiles are
// fetched asynchronously (16B copies straight gmem->smem, no register
// round-trip, no sync-copy stall). Each CTA computes a partial (BM x BN)
// tile over a contiguous chunk of K and atomically accumulates into C
// (C is zero-initialized by the caller).
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src) {
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(dst), "l"(gmem_src));
}
__device__ __forceinline__ void cp_async_commit_group() {
  asm volatile("cp.async.commit_group;\n" ::);
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}
template <typename T, int STAGES>
__global__ static void
gemm_splitk_kernel(const T* __restrict__ A,
                   const T* __restrict__ B,
                   T* __restrict__ C,
                   int M, int N, int K,
                   int k_tiles_per_split)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 32;
  constexpr int SA = BM * (BK + 4);   // floats per A stage (+4 padding kills bank conflicts)
  constexpr int SB = BN * BK;         // floats per B stage
  extern __shared__ char smem_raw[];
  T* smemA = reinterpret_cast<T*>(smem_raw);
  T* smemB = reinterpret_cast<T*>(smem_raw) + STAGES * SA;
  const int tid = (int)threadIdx.x;
  const int m0 = (int)blockIdx.x * BM;
  const int n0 = (int)blockIdx.y * BN;
  const int k_tiles_total = K / BK;
  const int k_begin = (int)blockIdx.z * k_tiles_per_split;
  int k_end = k_begin + k_tiles_per_split;
  if (k_end > k_tiles_total) k_end = k_tiles_total;
  const int ntiles = k_end - k_begin;
  // Async global->shared stage loader: 16B cp.async copies, fully coalesced.
  auto load_stage = [&](int stage, int kt) {
    T* sA = smemA + stage * SA;
    T* sB = smemB + stage * SB;
    const T* gA = A + (long)m0 * K + (long)kt * BK;   // A tile (BM x BK), K-contiguous
    const T* gB = B + (long)kt * BK * N + n0;         // B tile (BK x BN), N-contiguous
    // A: 128 rows x 8 float4 = 1024 float4; 4 per thread
    CUTE_UNROLL
    for (int i = 0; i < 4; ++i) {
      int idx = tid + i * 256;
      int row = idx >> 3;
      int c4  = idx & 7;
      cp_async16(sA + row * (BK + 4) + c4 * 4, gA + (long)row * K + c4 * 4);
    }
    // B: 32 rows x 32 float4 = 1024 float4; 4 per thread
    CUTE_UNROLL
    for (int i = 0; i < 4; ++i) {
      int idx = tid + i * 256;
      int row = idx >> 5;
      int n4  = idx & 31;
      cp_async16(sB + row * BN + n4 * 4, gB + (long)row * N + n4 * 4);
    }
  };
  // C tile + 16x16 thread layout -> 8x8 register accumulators per thread
  // (warp lanes share A rows via padded-smem broadcast and sweep 16
  // consecutive B columns in distinct banks, as before).
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));   // (M,N)
  Tensor gC = local_tile(mC, make_shape(Int<BM>{}, Int<BN>{}),
                         make_coord((int)blockIdx.x, (int)blockIdx.y));                    // (BM,BN)
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));
  Tensor tCgC = local_partition(gC, tC, tid, Step<_1,_1>{});   // (8,8)
  Tensor tCrC = make_tensor_like(tCgC);                        // (8,8) accumulators
  clear(tCrC);
  if (ntiles > 0) {
    // Prologue: fill the first STAGES-1 pipeline stages (commit even when
    // empty so commit-group numbering stays aligned with k-tile indices).
    CUTE_UNROLL
    for (int s = 0; s < STAGES - 1; ++s) {
      if (s < ntiles) load_stage(s, k_begin + s);
      cp_async_commit_group();
    }
    for (int kt = 0; kt < ntiles; ++kt) {
      // Wait until tile kt's stage has landed (<= STAGES-2 groups in flight)
      cp_async_wait_group<STAGES - 2>();
      __syncthreads();
      const int stage = kt % STAGES;
      Tensor sA = make_tensor(make_smem_ptr(smemA + stage * SA),
                              make_layout(make_shape(Int<BM>{}, Int<BK>{}),
                                          make_stride(Int<BK + 4>{}, Int<1>{})));
      Tensor sB = make_tensor(make_smem_ptr(smemB + stage * SB),
                              make_layout(make_shape(Int<BN>{}, Int<BK>{}),
                                          make_stride(Int<1>{}, Int<BN>{})));
      Tensor tCsA = local_partition(sA, tC, tid, Step<_1, X>{});   // (8,BK)
      Tensor tCsB = local_partition(sB, tC, tid, Step< X,_1>{});   // (8,BK)
      // Prefetch the tile STAGES-1 ahead into its (now free) stage slot;
      // all threads finished the previous compute before the barrier above,
      // so overwriting that slot is safe.
      const int nk = kt + STAGES - 1;
      if (nk < ntiles) {
        load_stage(nk % STAGES, k_begin + nk);
      }
      cp_async_commit_group();
      // C += A * B on the current smem stage (overlaps the async prefetch)
      gemm(tCsA, tCsB, tCrC);
    }
    // Split-K reduction: accumulate partial tile into C
    CUTE_UNROLL
    for (int i = 0; i < size(tCrC); ++i) {
      atomicAdd(&tCgC(i), tCrC(i));
    }
  }
}

torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  const int64_t M = A.size(0);
  const int64_t K = A.size(1);
  const int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");

  constexpr int BM = 128, BN = 128, BK = 32;
  TORCH_CHECK(M % BM == 0 && N % BN == 0 && K % BK == 0,
              "Require M, N divisible by 128 and K divisible by 32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::zeros({M, N}, A.options());

  const int k_tiles_total = (int)(K / BK);
  const int tiles = (int)((M / BM) * (N / BN));

  // Pick the K split so that the grid fills the device.
  int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  int target_blocks = 4 * sm_count;
  int splits = target_blocks / tiles;
  if (splits < 1) splits = 1;
  if (splits > k_tiles_total) splits = k_tiles_total;
  int k_tiles_per_split = (k_tiles_total + splits - 1) / splits;

  constexpr int STAGES = 2;  // 3 stages needs 104,448 B dynamic smem > sm_89's 101,376 B max; 2 stages = 69,632 B
  constexpr int SMEM_BYTES = STAGES * (BM * (BK + 4) + BN * BK) * (int)sizeof(float);
  static bool smem_attr_ready = false;
  if (!smem_attr_ready) {
    cudaError_t attr_err = cudaFuncSetAttribute(
        gemm_splitk_kernel<float, STAGES>,
        cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    TORCH_CHECK(attr_err == cudaSuccess, "smem attribute failed: ",
                cudaGetErrorString(attr_err));
    smem_attr_ready = true;
  }
  dim3 grid((unsigned)(M / BM), (unsigned)(N / BN), (unsigned)splits);
  dim3 block(256);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_splitk_kernel<float, STAGES><<<grid, block, SMEM_BYTES, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)M, (int)N, (int)K,
      k_tiles_per_split);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE split-K GEMM launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

matmul_ext = load_inline(
    name="cute_splitk_gemm_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    C = A * B for A:(M,K), B:(K,N) with very large K, implemented with a
    single custom CuTe CUDA kernel: a tiled 128x128x32 GEMM with split-K
    across the huge reduction dimension, register-prefetch double buffering,
    and an atomic-accumulate epilogue into a zero-initialized C.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul_cute(A, B)

